private readonly AgentRenderThrottle _throttle = new(Clock);

private void OnEvent(RunEvent evt)
{
    Snapshot = Snapshot.Apply(evt);
    if (_throttle.ShouldRender())
    {
        StateHasChanged();
    }
}

// A host that repainted for its own reason must not wait out the previous window:
_throttle.Reset();
